@_documentation(visibility: private)
#endif
public func FfiConverterTypeSharedCollectionBinding_lift(_ buf: RustBuffer) throws -> SharedCollectionBinding {
    return try FfiConverterTypeSharedCollectionBinding.lift(buf)
}

